public sealed class DistinctApproverRequirement(string makerId) : IAuthorizationRequirement {
    public string MakerId { get; } = makerId;
}
public sealed class DistinctApproverHandler : AuthorizationHandler<DistinctApproverRequirement> {
    protected override Task HandleRequirementAsync(AuthorizationHandlerContext context, DistinctApproverRequirement req) {
        var me = context.User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (me is not null && me != req.MakerId) context.Succeed(req);
        return Task.CompletedTask;
    }
}
